import math

def is_square(k):
    if k < 0:
        return False
    root = int(math.isqrt(k))
    return root * root == k

def is_cool_backtracking(n):
    """
    Checks if n is a cool integer using backtracking (DFS).
    """

    # Optimization: If the total sum is a square, n is not cool.
    T_n = n * (n + 1) // 2
    if is_square(T_n):
        return False

    def backtrack(current_permutation, remaining_numbers, current_sum):
        if len(current_permutation) == n:
            return True

        for i in range(len(remaining_numbers)):
            next_x = remaining_numbers[i]
            next_sum = current_sum + next_x

            if not is_square(next_sum):
                new_remaining = remaining_numbers[:i] + remaining_numbers[i+1:]

                if backtrack(current_permutation + [next_x], new_remaining, next_sum):
                    return True

        return False

    initial_numbers = list(range(1, n + 1))
    return backtrack([], initial_numbers, 0)

# --- Main Execution ---
N_TARGET = 2200 # Searching significantly higher than 2025 based on density estimate
cool_integers = []
count = 0

print(f"Starting computational search for N up to {N_TARGET} to find the 2025th cool integer...")

for n in range(1, N_TARGET + 1):
    try:
        is_cool = is_cool_backtracking(n)
    except RecursionError:
        print(f"Warning: Recursion depth exceeded for N={n}. Stopping search.")
        break

    if is_cool:
        cool_integers.append(n)
        count += 1
        if count == 2025:
            print(f"Found the 2025th cool integer: {n}")
            break

print(f"\nSearch complete. Found {count} cool integers.")

